@Component("coupon-entity-projector")
public class CouponEntityProjector implements EntityProjector<Coupon>{
		
	// core constructor
	public CouponEntityProjector(ProjectorRegistry registry,
										CouponRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Coupon> getEntityClass() {
		return Coupon.class;
	}

    /*
	 * Insert a Coupon
	 * 
     * @param	entity Coupon
     */
    public Coupon create( Coupon entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Coupon
	 * 
     * @param	entity Coupon
     */
    public Coupon update( Coupon entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Coupon
	 * 
     * @param	id		UUID
     */
    public Coupon delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Coupon entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Promotion
     * 
     * @param	parentId	UUID
     * @param	assignment 	Promotion 
     * @return	Coupon
     */
    public Coupon assignPromotion( UUID parentId, Promotion assignment ) {
	    LOGGER.info("assigning Promotion as " + assignment.toString() );

	    Coupon parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Promotion.class, assignment.getPromotionId());

	    // ------------------------------------------
		// assign the Promotion to the parent entity
		// ------------------------------------------ 
	    parentEntity.setPromotion( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Promotion
	 * 
	 * @param	parentId		UUID
	 * @return	Coupon
	 */
	public Coupon unAssignPromotion( UUID parentId ) {
		Coupon parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Promotion on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Promotion on the parent entithy
		// ------------------------------------------     
	    parentEntity.setPromotion(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Redemptions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Coupon
     */
    public Coupon addToRedemptions( UUID parentId, CouponRedemption addTo ) {
	    LOGGER.info("handling AssignRedemptionsToCouponEvent - " );
	    
	    Coupon parentEntity = repository.findById(parentId).get();
	    CouponRedemption child = registry.project( CouponRedemption.class, addTo.getCouponRedemptionId());
	    
	    parentEntity.getRedemptions().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Redemptions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Coupon
     */
	public Coupon removeFromRedemptions( UUID parentId, CouponRedemption removeFrom ) {
	    LOGGER.info("handling RemoveRedemptionsFromCouponEvent " );
	
	    Coupon parentEntity = repository.findById(parentId).get();
	    CouponRedemption child = registry.project( CouponRedemption.class, removeFrom.getCouponRedemptionId());
	    
	    parentEntity.getRedemptions().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Coupon via an FindCouponQuery
     * @return 	query	FindCouponQuery
     */
    @SuppressWarnings("unused")
    public Coupon find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Coupon - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Coupons
     *
     * @param	query	FindAllCouponQuery 
     * @return 	List<Coupon> 
     */
    @SuppressWarnings("unused")
    public List<Coupon> findAll( FindAllCouponQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Coupon - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final CouponRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(CouponEntityProjector.class.getName());

}
